const CRM_ORIGIN='https://doc-freela.vendr2017.chatgpt.site';
const json=(body,status=200,headers={})=>new Response(JSON.stringify(body),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store',...headers}});
const cors={'access-control-allow-origin':CRM_ORIGIN,'access-control-allow-methods':'GET,POST,PUT,OPTIONS','access-control-allow-headers':'Content-Type,X-Edit-Token'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const currency=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(n)||0);
const safeColor=(s,fallback)=>/^#[0-9a-fA-F]{6}$/.test(s||'')?s:fallback;
const hash=async s=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))).map(x=>x.toString(16).padStart(2,'0')).join('');
const validId=s=>/^[0-9a-f-]{36}$/i.test(s||'');
function checkedQuote(value){if(!value||typeof value!=='object'||!String(value.title||'').trim()||!Array.isArray(value.items)||!value.items.length)throw Error('Preencha título e serviços.');const items=value.items.slice(0,40).map(x=>({name:String(x.name||'').slice(0,150),description:String(x.description||'').slice(0,500),quantity:Math.min(100000,Math.max(0,Number(x.quantity)||1)),price:Math.min(100000000,Math.max(0,Number(x.price)||0))}));if(items.some(x=>!x.name))throw Error('Informe os serviços.');const branding=value.branding||{};return {number:String(value.number||'').slice(0,40),title:String(value.title).slice(0,200),clientName:String(value.clientName||'').slice(0,160),clientEmail:String(value.clientEmail||'').slice(0,160),description:String(value.description||'').slice(0,4000),payment:String(value.payment||'').slice(0,1000),delivery:String(value.delivery||'').slice(0,500),terms:String(value.terms||'').slice(0,4000),validity:String(value.validity||'').slice(0,20),issued:String(value.issued||'').slice(0,20),discount:Math.max(0,Number(value.discount)||0),items,branding:{logo:String(branding.logo||'').slice(0,450000),favicon:String(branding.favicon||'').slice(0,450000),primary:safeColor(branding.primary,'#ff6937'),secondary:safeColor(branding.secondary,'#06b6d4'),intro:String(branding.intro||'').slice(0,1500),footer:String(branding.footer||'').slice(0,1000),thanks:String(branding.thanks||'').slice(0,500),agencyName:String(branding.agencyName||'').slice(0,120),tagline:String(branding.tagline||'').slice(0,180),about:String(branding.about||'').slice(0,2500),methodology:String(branding.methodology||'').slice(0,2500),portfolio:String(branding.portfolio||'').slice(0,2000),contactEmail:String(branding.contactEmail||'').slice(0,160),contactPhone:String(branding.contactPhone||'').slice(0,80),website:String(branding.website||'').slice(0,300),headline:String(branding.headline||'').slice(0,180),welcome:String(branding.welcome||'').slice(0,1200),approvalLabel:String(branding.approvalLabel||'').slice(0,70),showReviews:branding.showReviews===true,reviews:(Array.isArray(branding.reviews)?branding.reviews:[]).slice(0,6).map(x=>({name:String(x.name||'').slice(0,120),rating:Math.min(5,Math.max(1,Number(x.rating)||5)),comment:String(x.comment||'').slice(0,1000),photo:String(x.photo||'').slice(0,45000)})),showProjects:branding.showProjects===true,maxProjects:Math.min(6,Math.max(1,Number(branding.maxProjects)||4)),projects:(Array.isArray(branding.projects)?branding.projects:[]).slice(0,6).map(x=>({title:String(x.title||'').slice(0,160),client:String(x.client||'').slice(0,120),description:String(x.description||'').slice(0,1000),url:String(x.url||'').slice(0,300),image:String(x.image||'').slice(0,45000)}))}}}
function proposalPage(q){const p=JSON.parse(q.payload),b=p.branding,subtotal=p.items.reduce((n,x)=>n+x.quantity*x.price,0),total=Math.max(0,subtotal-p.discount);const logo=/^data:image\/(png|jpeg|webp);base64,[a-zA-Z0-9+/=]+$/.test(b.logo)?`<img class="logo" src="${b.logo}" alt="Logo da empresa">`:'<span class="mark">D</span>';const approved=q.status==='aprovado',site=/^https:\/\/[^\s<>"']+$/.test(b.website||'')?b.website:'';return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(p.title)} · Proposta comercial</title>${/^data:image\/(png|jpeg|webp);base64,[a-zA-Z0-9+/=]+$/.test(b.favicon)?`<link rel="icon" href="${b.favicon}">`:''}<style>:root{--brand:${b.primary};--second:${b.secondary}}*{box-sizing:border-box}body{margin:0;background:#090909;color:white;font:15px/1.6 Inter,Arial,sans-serif}.shell{max-width:1030px;margin:0 auto;padding:50px 22px}.hero{text-align:center;padding:45px 20px}.logo{max-width:220px;max-height:100px;object-fit:contain}.mark{display:inline-grid;place-items:center;background:var(--brand);color:#fff;width:62px;height:62px;border-radius:50%;font-size:36px;font-weight:bold}.eyebrow{margin:25px auto 5px;color:var(--brand);text-transform:uppercase;letter-spacing:.1em}.agency-name{font-weight:700;font-size:17px;margin:12px 0 0}.agency-copy{white-space:pre-line}.hero h1{font-size:clamp(30px,5vw,52px);line-height:1.08;margin:12px 0}.muted{color:#aaa}.grid{display:grid;grid-template-columns:2fr 1fr;gap:20px}.panel{border:1px solid #292929;border-radius:14px;background:#121212;padding:26px;margin-bottom:20px}h2{font-size:19px;margin:0 0 15px}.item{padding:15px 0;border-top:1px solid #292929;display:flex;justify-content:space-between;gap:20px}.item small{display:block;color:#aaa}.item b{white-space:nowrap;color:var(--brand)}.review{display:flex;gap:15px;padding:16px 0;border-top:1px solid #292929}.review img{width:54px;height:54px;border-radius:50%;object-fit:cover}.stars{color:var(--second)}.project-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.project{border:1px solid #292929;border-radius:10px;overflow:hidden;padding:15px}.project img{width:100%;height:170px;object-fit:cover;border-radius:7px}.project h3{margin:9px 0 0}.agency-panel p{white-space:pre-line;color:#bbb}.agency-contact a{color:var(--brand);overflow-wrap:anywhere}.total{display:flex;justify-content:space-between;border-top:1px solid #333;padding-top:16px;font-size:24px;font-weight:bold;color:var(--brand)}.brand-button{width:100%;border:0;border-radius:10px;background:linear-gradient(100deg,var(--brand),var(--second));color:white;padding:15px;font-weight:bold;font-size:17px;cursor:pointer}.brand-button:disabled{opacity:.6;cursor:default}label{display:block;margin:12px 0}input{width:100%;padding:12px;background:#090909;color:#fff;border:1px solid #444;border-radius:8px;font:inherit}.success{color:#03bf8b;text-align:center}.error{color:#ff6b74}footer{text-align:center;color:#999;margin-top:35px}@media(max-width:700px){.grid,.project-grid{grid-template-columns:1fr}.shell{padding:15px}.hero{padding:30px 10px}}</style></head><body><main class="shell"><div class="hero">${logo}${b.agencyName?`<p class="agency-name">${esc(b.agencyName)}</p>`:''}${b.tagline?`<p class="muted">${esc(b.tagline)}</p>`:''}<p class="eyebrow">Proposta comercial</p><h1>${esc(b.headline||p.title)}</h1>${b.welcome?`<p class="muted agency-copy">${esc(b.welcome)}</p>`: ''}<p class="muted">Orçamento ${esc(p.number)} · Para ${esc(p.clientName||'cliente')}</p>${p.description?`<p>${esc(p.description)}</p>`:''}</div><div class="grid"><div><section class="panel"><h2>Detalhes da proposta</h2>${b.intro?`<p class="muted">${esc(b.intro)}</p>`:''}${p.items.map(x=>`<div class="item"><div>${esc(x.name)}<small>${esc(x.description)}${x.quantity!==1?' · '+x.quantity+' un.':''}</small></div><b>${currency(x.quantity*x.price)}</b></div>`).join('')}<div class="item"><span>Subtotal</span><span>${currency(subtotal)}</span></div>${p.discount?`<div class="item"><span>Desconto</span><span>− ${currency(p.discount)}</span></div>`:''}<div class="total"><span>Total</span><span>${currency(total)}</span></div></section></div><aside><section class="panel"><h2>Condições</h2>${p.payment?`<p><b>Pagamento</b><br>${esc(p.payment)}</p>`:''}${p.delivery?`<p><b>Entrega</b><br>${esc(p.delivery)}</p>`:''}${p.validity?`<p><b>Validade</b><br>${esc(p.validity)}</p>`:''}</section></aside></div>${b.about||b.methodology||b.portfolio?`<section class="panel agency-panel">${b.about?`<h2>Sobre ${esc(b.agencyName||'nós')}</h2><p>${esc(b.about)}</p>`:''}${b.methodology?`<h2>Como trabalhamos</h2><p>${esc(b.methodology)}</p>`:''}${b.portfolio?`<h2>Portfólio e resultados</h2><p>${esc(b.portfolio)}</p>`:''}</section>`:''}${b.contactEmail||b.contactPhone||site?`<section class="panel agency-contact"><h2>Fale com a agência</h2>${b.contactEmail?`<p>E-mail: <a href="mailto:${esc(b.contactEmail)}">${esc(b.contactEmail)}</a></p>`:''}${b.contactPhone?`<p>WhatsApp: ${esc(b.contactPhone)}</p>`:''}${site?`<p>Site: <a href="${esc(site)}" target="_blank" rel="noopener noreferrer">${esc(site)}</a></p>`:''}</section>`:''}${b.showReviews&&Array.isArray(b.reviews)&&b.reviews.some(x=>x.name&&x.comment)?`<section class="panel"><h2>Avaliações de Clientes</h2>${b.reviews.filter(x=>x.name&&x.comment).map(x=>`<div class="review">${/^data:image\/(png|jpeg|webp);base64,[a-zA-Z0-9+/=]+$/.test(x.photo)?`<img src="${x.photo}" alt="">`:''}<div><b>${esc(x.name)}</b><div class="stars">${'★'.repeat(Math.min(5,Math.max(1,Number(x.rating)||5)))}</div><p class="agency-copy">${esc(x.comment)}</p></div></div>`).join('')}</section>`:''}${b.showProjects&&Array.isArray(b.projects)&&b.projects.some(x=>x.title)?`<section class="panel"><h2>Projetos do Portfólio</h2><div class="project-grid">${b.projects.filter(x=>x.title).slice(0,Math.min(6,Math.max(1,Number(b.maxProjects)||4))).map(x=>`<article class="project">${/^data:image\/(png|jpeg|webp);base64,[a-zA-Z0-9+/=]+$/.test(x.image)?`<img src="${x.image}" alt="${esc(x.title)}">`:''}<h3>${esc(x.title)}</h3>${x.client?`<small class="muted">${esc(x.client)}</small>`:''}<p class="agency-copy">${esc(x.description)}</p>${/^https:\/\/[^\s<>"']+$/.test(x.url||'')?`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Ver projeto ↗</a>`:''}</article>`).join('')}</div></section>`:''}${p.terms?`<section class="panel"><h2>Termos e condições</h2><p>${esc(p.terms)}</p></section>`:''}<section class="panel" id="approval">${approved?`<h2 class="success">✓ Proposta aprovada</h2><p class="success">${esc(b.thanks||'Obrigado pela parceria. Entraremos em contato em breve!')}</p>`:`<h2>Aprovar proposta</h2><p class="muted">Ao aprovar, seus dados e a data da aprovação ficam registrados.</p><form id="form"><label>Seu nome<input name="name" required maxlength="120" autocomplete="name"></label><label>E-mail<input name="email" type="email" required maxlength="160" autocomplete="email"></label><label><input name="consent" type="checkbox" required style="width:auto"> Li e aceito a proposta e as condições acima.</label><p id="message" class="error"></p><button class="brand-button">✓ ${esc(b.approvalLabel||'Aprovar proposta')}</button></form>`}</section><footer>${esc(b.footer||'DOC.FREELA · Proposta comercial')}</footer></main><script>document.querySelector('#form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button'),m=document.querySelector('#message');b.disabled=true;m.textContent='';try{const r=await fetch('/api/quotes/${q.id}/approve',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name:f.elements.namedItem('name').value,email:f.elements.namedItem('email').value,consent:f.elements.namedItem('consent').checked})});const data=await r.json();if(!r.ok)throw Error(data.error||'Não foi possível aprovar.');location.reload()}catch(err){m.textContent=err.message;b.disabled=false}})</script></body></html>`}
export default {async fetch(request,env){const url=new URL(request.url),origin=request.headers.get('origin');if(request.method==='OPTIONS')return new Response(null,{status:204,headers:origin===CRM_ORIGIN?cors:{}});const ch=origin===CRM_ORIGIN?cors:{};try{if(url.pathname==='/health')return json({ok:true,db:!!env.DB});if(url.pathname==='/favicon.ico')return new Response(null,{status:204});if(url.pathname==='/'&&request.method==='GET')return new Response('<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>DOC.FREELA · Propostas</title><body style="background:#090909;color:white;font:16px Arial;text-align:center;padding:15vh 20px"><h1>DOC.FREELA · Propostas</h1><p>Abra o link enviado para visualizar sua proposta comercial.</p></body></html>',{headers:{'content-type':'text/html; charset=utf-8'}});if(!env.DB)return json({error:'Armazenamento indisponível'},503,ch);if(url.pathname==='/api/quotes'&&request.method==='POST'){if(origin!==CRM_ORIGIN)return json({error:'Origem não permitida'},403,ch);const raw=await request.text();if(raw.length>1100000)return json({error:'Proposta excede o limite de tamanho'},413,ch);const data=JSON.parse(raw),p=checkedQuote(data.quote);const id=crypto.randomUUID(),secret=String(data.editToken||'');if(secret.length<32)return json({error:'Chave de edição inválida'},400,ch);const now=new Date().toISOString();await env.DB.prepare('INSERT INTO quotes (id,edit_hash,payload,status,created_at,updated_at) VALUES (?,?,?,?,?,?)').bind(id,await hash(secret),JSON.stringify(p),'rascunho',now,now).run();return json({id,status:'rascunho',url:`${url.origin}/p/${id}`},201,ch)}const m=url.pathname.match(/^\/api\/quotes\/([a-f0-9-]{36})(?:\/(approve))?$/i);if(m&&validId(m[1])){const row=await env.DB.prepare('SELECT * FROM quotes WHERE id=?').bind(m[1]).first();if(!row)return json({error:'Proposta não encontrada'},404,ch);if(m[2]==='approve'&&request.method==='POST'){if(row.status==='aprovado')return json({status:'aprovado'},200,ch);const body=await request.json(),name=String(body.name||'').trim().slice(0,120),email=String(body.email||'').trim().slice(0,160);if(!body.consent||!name||!/^\S+@\S+\.\S+$/.test(email))return json({error:'Informe nome, e-mail e aceite as condições'},400,ch);const now=new Date().toISOString();await env.DB.prepare("UPDATE quotes SET status='aprovado',approver_name=?,approver_email=?,approved_at=?,updated_at=? WHERE id=? AND status!='aprovado'").bind(name,email,now,now,row.id).run();return json({status:'aprovado',approvedAt:now},200,ch)}if(request.method==='GET'&&!m[2])return json({id:row.id,status:row.status,approvedAt:row.approved_at,approverName:row.approver_name,approverEmail:row.approver_email},200,ch);if(request.method==='PUT'&&!m[2]){if(origin!==CRM_ORIGIN)return json({error:'Origem não permitida'},403,ch);const secret=request.headers.get('x-edit-token')||'';if(await hash(secret)!==row.edit_hash)return json({error:'Não autorizado'},403,ch);if(row.status==='aprovado')return json({error:'Proposta aprovada não pode ser alterada'},409,ch);const raw=await request.text();if(raw.length>1100000)return json({error:'Proposta excede o limite de tamanho'},413,ch);const p=checkedQuote(JSON.parse(raw).quote);await env.DB.prepare('UPDATE quotes SET payload=?,updated_at=? WHERE id=?').bind(JSON.stringify(p),new Date().toISOString(),row.id).run();return json({id:row.id,status:row.status,url:`${url.origin}/p/${row.id}`},200,ch)}}const page=url.pathname.match(/^\/p\/([a-f0-9-]{36})$/i);if(page&&request.method==='GET'){const row=await env.DB.prepare('SELECT * FROM quotes WHERE id=?').bind(page[1]).first();if(!row)return new Response('Proposta não encontrada',{status:404});return new Response(proposalPage(row),{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store','content-security-policy':"default-src 'self' data:; script-src 'unsafe-inline' 'self'; style-src 'unsafe-inline' 'self'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'"}})}return new Response('Página não encontrada',{status:404})}catch(error){console.error('quote request failed',error);return json({error:error instanceof SyntaxError?'Dados inválidos':'Não foi possível concluir a operação'},500,ch)}}};
